      'severity': ScoreQuestion(
        'Rate the severity of this issue',
        criteria: ['cosmetic', 'workaround', 'blocking'],
      ),
    },
  ),
);

for (final entry in response.answers.entries) {
  print('${entry.key}: ${entry.value}');
}

client.close();
```

